sys_rte_eb_multiple_input_output_script_.script:
(function(batch, output) {
   for (var i = 0; i < batch.length; i++) {
      var input = batch[i].input; // Value of the input columns concatenated with '|'.

      var map = {
         'Inicial':            ['Ideation', 'Under Evaluation','6'],   // Inicial → Ideation + Under Evaluation
         'Em desenvolvimento': ['Design', 'Build','0'],   // Implementando →
         'Em produção':        ['Operational', 'In Use','1'],   // Em produção → In Use
         'Suspenso':           ['End of Life', 'Obsolete','5'],   // Suspenso → Pending Retirement
         'Desativado':         ['End of Life', 'Retired','3']    // Desativado → Retired
      }
      var lifeCycle = map[input];
      if(!lifeCycle) {
         output[i].life_cycle_stage = 'Unknown';
         output[i].life_cycle_stage_status = 'Unknown';
         output[i].install_status = '-1';
      } else {
         output[i].life_cycle_stage = lifeCycle[0];
         output[i].life_cycle_stage_status = lifeCycle[1];
         output[i].install_status = lifeCycle[2];
      }
   }
})(batch, output);
